   "name": "五类关系：生 · 克 · 泄 · 耗 · 比（老师的定义）",
   "rule": "生：一个事物把自己**自己的能量**传输给另一个事物，使对方变强、己方变弱——这条纽带叫生。\n克：一个事物用**自身的力量**去压制、攻击另一个事物，使对方变弱——这条纽带叫克。\n泄：一个事物把另一个事物的力量**吸收到自己身上**，使自己变强、对方变弱——叫泄。\n耗：一个事物**被**另一个事物克制、攻击，从而使主克的一方减力而消耗——叫耗。\n比：一个事物与另一个事物相互分享、劫杀，使彼此力量达成平均——叫比。\n⚠️ 五类都是**两个事物之间的关系（纽带）**，不是五种东西，也不是「谁打赢谁」。\n⚠️ 这五类是**老师讲五行时给的完整定义**；**断卦时不用「泄／耗」当关系名**，见 W21。",
