   "rule": "同一件事、同一个「克」，落在什么体量的对象上，结果完全不同：\n「同样是一个成年人壮汉来打你，那你是一个小孩呢，还是一个壮汉呢，还是泰森拳王呢？那你是不是你所被克的这个结果也不一样呢？」\n反过来也一样：「到底是个小孩子克你呢，还是一个成年人壮汉克你呢，还是一个拳王泰森来克你呢？那你所受的伤害是不是不一样呢？」\n★ 所以断「克」时要看**双方体量**（自己体量多大、对方力量有多大），不是判一个「克得动／克不动」的有无。他讲风水量化时说的同一句话：「我的楼层本身的体量怎么样？我是大楼还是小房子，它的体量有多大？」",
