   "rule": "老师自述这是他个人总结的「预测的三大逻辑」，三种方法「互相佐用、互相应证」。\n★ **名称有过一次改动**：058（2022-04-16）标题与正文两次作「**关系论、定位论、象义论**」（页面旁注「定位论、宫位论」）；043（后来重讲）改称「关系论、**宫位论**、象义论」。⇒ 同源两名，引用写「定位论（后称宫位论）」。\n· **关系论**：卦象、命象之间的作用关系；「建立在太极的基础上，以时间为使用原则」。落到小六壬＝生克、三宫互作、男问女问、白天夜里问。\n· **定位论**：「不同的事件有不同的定位信息，这种定位信息源自于空间属性的作用」。落到小六壬＝三宫各自的空间信息（天时宫＝外环境/领导/起因……）。\n· **象义论**：「对时间与空间所表达信息的**高度总结**」；「时间与空间的作用共同呼应共振的结果」。⇒ 关系、定位、吉凶三条线都指向同一处时，那才是象义；「只需在事件的分析中提取最为呼应的信息」。",
