   "name": "全息卦：一个卦断一个人（面相·性格·健康·伤灾·事业·财运·感情）",
   "rule": "**定义**：「建立在小六壬卜法的预测原则之上**对宏观方向进行分析**的方法」；「这一种预测方式**没有特殊的技法**，只需要建立一个更大、更广的太极即可入手」；「由于这种卦往往更具有指向性，所以一般取卦的方式尽量以**事主的固定信息**为主，如八字、姓名笔画等……较为简洁的方式是报数」。\n**三宫分工**：「人宫代表了**综合信息**，天宫代表了**先天影响**，地宫代表了**后天影响**」。\n**逐项对应**：\n- 面相：落宫定轮廓，天地两宫定突出部位（例：赤口＝棱角分明/颧骨高/眉骨高/下颌线明显；双速喜火 ⇒ 额头、眼睛突出）\n- 性格：「赤口为主，天为**外在表现**，地为**内在表现**」——「在外是表现给不熟悉的人看的，在内是表现给自己或者家人看的」\n- 健康：先以落宫定基本范围与属性，再定部位，最后三宫合看；且要说**表象**（不是「胃不好」，而是胃炎/胃溃疡/胀气/胃下垂）、要**结合实际年纪**\n- 伤灾：落宫定范围与属性 → 部位 → 三宫合看（烫伤、爆炸伤、尖角伤等）；「**无伤则痣、胎记**」\n- 事业：落宫＝主要方向；天宫＝外在环境/机遇/领导/个人能力；地宫＝成绩/执行/方法/成效；天地皆克落宫＝**官杀**（行动力强、易得领导喜欢、易有官职，但也易被同事压榨、功劳被抢）\n- 财运：天宫＝财源；地宫＝财库（**宏观概念**，不是「存不住钱」）；落宫＝当下财运\n- 感情：天宫＝缘分，地宫＝相处模式，落宫＝综合\n**铁律**：「卦是**全息**的」——火金出现时土木水也受影响，「无非是直接影响还是间接影响」；且「最后都一定一定要建立在**原卦的基础格局**之上」。\n**弊**：「全息卦虽然可以用一个卦对事主多方面信息进行预测，就**一定会有它的弊端和相对性**」。",
