   "rule": "**① 射覆：理射覆可以，蒙不行。**「不建议新手玩射覆」「一上来直接断是什么物品，这叫**蒙**」；「理论射覆」靠六神三才先把范围缩小。他最恨的是事后硬套：「**射覆完了，发现三宫套不了，加个月令、12 时辰、旺衰**，就是没想过到底是什么根本原因」。\n**② 物品类（衣服、器物）的吉凶只用来判「过不过关」。**「这种卦，如果你只看什么大吉小吉、大凶小凶，那完蛋了」「考虑吉凶是为了先界定这个东西本身的质量**是否过关**」：三吉⇒过关；三凶⇒「远远都对不起这价格」。质量好坏是客观现象，落到不同人身上感受不同——「**没有最对的，只有最合适的**」。\n**③ 二选一的卦，只看象，不论吉凶。**问「在学校还是在家」，落宫只给「在哪一边」的象；落宫不够明显就先问背景，别硬用吉凶压出答案。\n**④ 阶段不同、太极点不同，生克关系也不同。**「但是**阶段不同，太极点不同，生克的关系也会不同**」——同一件事在没办成前与办成后，克我可以变成生我（文书证书：没拿到＝奔波的克，拿到＝敲门砖的生）。",
