   "rule": "★ **先看效力**：这句话出自群里的**三哥**（学员），**本份里没有老师本人把「条件不足」定为赤口定义的原句**。所以它**不进断卦判据**，只在取象卡住时当一个思路提示，⛔ 不许当成赤口的定义去用。\n\n原话场景（072，2024-11-29 雪休卦：留连·赤口·赤口 辰时，问今天能否雪休；实际放假，断「不能」的翻车）：\n· 学生：「赤口 通常表示**条件不足**，而不是直接的否定」——「体用又是生内的」\n· 老师接着往下说：「**不满足就谈嘛，拉扯拉扯嘛**」——即赤口不是一句“不行”了事，而是还有争、还有谈的余地。\n\n**同向的旁证（这两条是老师本人的）**：\n· 077／107 物品卦：「考虑吉凶是为了先界定这个东西本身的质量**是否过关**」——吉凶只定过关与否，不等于否定这件东西。\n· 083：赤口断出行＝车祸、断生意＝破财纠纷，都不是「没有」，而是「有，且是争与损」。\n⇒ 用法上可以这么记：**赤口回答的是「有争、有条件差」，不是「彻底没有」**；“没有”是空亡的活儿。",
