   "rule": "老师 063 当场列的留连主数：**排位数 2、8｜八卦数 7、8｜五行数 5、10｜天干数 6**（地支数没给全）。★ 取数时要把**本数**与**借数**分开：「5 是借的，7 是**本数**」；「7 为留连的本数，且**与卦象属性相符**，所以作为优先考虑」（艮为土，留连亦为土）。\n⚠️ 这是 063 现场口述的一宫之数，**不能当成六宫通表的定论**；其余五宫的同类数须另找出处，找不到就写「材料未载」。",
