     "quote": "起卦的时候 以天为体 看天气 以人为体 看吉凶｜天宫代表了气、先天条件，地宫一定程度代表了地理环境、当地气温｜你要看天气为什么不直接问天气，要问下不下雪？这样天气问题就变成了一个掺杂了吉凶观念的问题",
