    "quote": "就是把速喜转到东南，留连转到正东，大安转到东北，留连转到正北，小吉转到西北，留连转到正西，赤口转到西南、留连转到正南｜看外部的，就把天宫排在用所表示的位置，看内部的，就把人宫排在用所表示的位置",
