/* ---------- 六、便捷取值（供 buildBlocks 用） ---------- */
export function gongField(name, field) {
  const g = GONG_MAP[name];
  return g && g[field] ? g[field].v : undefined;
}
export function gongSrc(name, field) {
  const g = GONG_MAP[name];
  return g && g[field] ? g[field].src : undefined;
}
export function ruleById(id) {
  const flat = [];
  const walk = (o) => {
    for (const k of Object.keys(o || {})) {
      const v = o[k];
      if (v && typeof v === 'object') {
        if (v.name && (v.rule || v.quotes)) flat.push({ id: k, ...v });
        walk(v);
      }
    }
  };
  walk(RULES);
  return flat.find((r) => r.id === id);
}

